EditorApplication.delayCall+=()=>{try{var rows=new List<string>();foreach(string name in new[]{"StreetLoopGreybox","ForestLoopReverse"}){UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/"+name+".unity");Physics.SyncTransforms();rows.Add(name+" branches="+string.Join(", ",UnityEngine.Object.FindObjectsByType<Racer.WoodlandRoute>().Select(b=>b.title)));foreach(var p in new[]{new Vector3(140,40,-88),new Vector3(120,40,-95),new Vector3(96.1f,38.8f,-108.6f)}){rows.Add("At "+p);foreach(var h in Physics.RaycastAll(new Vector3(p.x,200,p.z),Vector3.down,250,~0,QueryTriggerInteraction.Ignore).OrderBy(h=>h.distance))rows.Add(h.collider.name+" "+h.point);} }
System.IO.File.WriteAllLines("Docs/Backyard/corridor-physical.txt",rows);UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/StreetLoopGreybox.unity");}catch(Exception e){System.IO.File.WriteAllText("Docs/Backyard/corridor-error.txt",e.ToString());}};return "Scheduled physical scene comparison";
